 unsigned nearest(RGB target)const{unsigned best=~0u,result=0u;for(unsigned candidate=0;candidate<256u;++candidate){const auto p=rgb(candidate);unsigned distance=0u;constexpr unsigned weight[]{2u,4u,3u};for(unsigned lane=0;lane<3u;++lane)distance+=weight[lane]*(p[lane]>target[lane]?p[lane]-target[lane]:target[lane]-p[lane]);if(distance<best){best=distance;result=candidate;}}return result;}
