inline Observation verify(const World&w,b::HeapAdapter&h,unsigned eax,const ra2::platform::x87::Image&fp,const std::vector<unsigned char>&bi,const std::vector<unsigned char>&ba,const unsigned char*image,const unsigned char*arena){need(h.events().size()==29u&&h.snapshots.empty()&&h.allocation_flags.size()==29u,"1080 exact29targetalloc/no frees/events");const auto p=w.prove(h);Observation o;o.events=h.events();auto expected=ba,ei=bi;b::word(expected,w.receiver()-w.base,p.address[0u]);b::word(expected,w.receiver()-w.base+4u,p.address[1u]);b::word(expected,w.registry()-w.base+4u*w.c.index,p.address[1u]);for(unsigned k=0;names[w.c.name][k];++k)expected[w.name()-w.base+k]=static_cast<unsigned char>(names[w.c.name][k]);b::word(ei,0x439490u,w.c.index+1u);need(std::equal(expected.begin(),expected.end(),arena)&&std::equal(ei.begin(),ei.end(),image),"1080 independent full image/arena/name/cache/registry/output graph oracle");o.image=ei;o.arena=expected;b::word(o.arena,w.receiver()-w.base,p.token(b::readword(o.arena,w.receiver()-w.base),0u));b::word(o.arena,w.receiver()-w.base+4u,p.token(b::readword(o.arena,w.receiver()-w.base+4u),1u));b::word(o.arena,w.registry()-w.base+4u*w.c.index,p.token(b::readword(o.arena,w.registry()-w.base+4u*w.c.index),1u));o.normalizations=3u;
 for(unsigned id=0;id<29u;++id){const auto&e=o.events[id];need(e.kind==b::Event::Kind::allocate&&e.ordinal==id&&e.size==p.size[id]&&e.address==p.address[id]&&e.result==p.address[id]&&h.allocation_flags[id]==0u,"1080 actual ordered allocation/rawresult/flags");std::vector<unsigned char>bytes(reinterpret_cast<const unsigned char*>(std::uintptr_t(p.address[id])),reinterpret_cast<const unsigned char*>(std::uintptr_t(p.address[id]))+p.size[id]);need(bytes==w.block(id,h),"1080 independent complete palette/colorconversion/nearest/ties/descriptors/roundedpadding oracle");o.heap_bytes+=p.size[id];if(id==1u){for(unsigned off:{0x170u,0x174u}){b::word(bytes,off,p.token(b::readword(bytes,off),3u));++o.normalizations;}b::word(bytes,0x178u,p.token(b::readword(bytes,0x178u),2u));++o.normalizations;for(unsigned j=0;j<25u;++j){const auto off=descriptors[j].field;b::word(bytes,off,p.token(b::readword(bytes,off),4u+j));++o.normalizations;}}else if(id>=4u){const auto&d=descriptors[id-4u];for(unsigned off=4u;off<d.bytes;off+=4u){const auto ref=off==4u?d.ref4:d.ref8;const auto ordinal=ref==0u?3u:ref==1u?2u:1u,offset=ref==2u?0x17cu:0u;b::word(bytes,off,p.token(b::readword(bytes,off),ordinal,offset));++o.normalizations;}}o.live.push_back(std::move(bytes));}
 need(eax==p.address[1u],"1080 complete rawEAX exact owned receiver identity");o.scalar=p.token(eax,1u);++o.normalizations;need(ra2::platform::x87::same_numeric(fp,w.expected_fp()),"1080 complete unchanged numeric x87");return o;}
